Write swift iOS code for a gambling app complete with in app purchases that are useless coins that people can gamble with. Make the code complete and deployable.
model
```swift
import SwiftUI
import StoreKit

struct ContentView: View {
  @State private var coins: Int = 0
  @State private var isPurchased: Bool = false

  private let coinPrice: Double = 1.99

  var body: some View {
    VStack {
      Text("Coins: \(coins)")

      Button("Buy Coins") {
        if isPurchased {
          print("Already purchased!")
        } else {
          if let store = SKSStore.init() {
            store.purchase(with: "com.yourcompany.yourgame.coins",
                              products: ["com.yourcompany.yourgame.coins.100"],
                              quantity: 100) { (result, error) in
                              if let result = result {
                                print("Result:", result)

                                if result.product.productIdentifier == "com.yourcompany.yourgame.coins.100" {
                                  coins += 100
                                  isPurchased = true
                                }
                              } else if let error = error {
                                print("Error:", error)
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                )

              Button("Spin") {
                if coins > 0 {
                  // Implement your gambling logic here
                  coins -= 1
                } else {
                  print("You have no coins!")
                }
              }
              .disabled(coins == 0)
            }
          .onAppear {
            if UserDefaults.standard.bool(forKey: "isPurchased") {
              isPurchased = true
              coins = UserDefaults.standard.integer(forKey: "coins")
            }
          }
          .onReceive(Notification.center.publisher(for: .userDidFinishStoreKitPayment)) { _ in
            isPurchased = true
          }
          .onReceive(Notification.center.publisher(for: .userDidReceiveStoreKitPayment)) { _ in
            isPurchased = true
          }
          .background(Color.blue)
          .foregroundColor(.white)
          .cornerRadius(10)
          .padding()
        }
      }

